import os
import boto3
from botocore.exceptions import ClientError

def normalize_expense(payload, config=None):
    config = config or {}
    client = boto3.client(
        'textract',
        aws_access_key_id=config.get('aws_access_key_id', os.environ.get('AWS_ACCESS_KEY_ID')),
        aws_secret_access_key=config.get('aws_secret_access_key', os.environ.get('AWS_SECRET_ACCESS_KEY')),
        region_name=config.get('region_name', os.environ.get('AWS_REGION', 'us-east-1'))
    )
    try:
        if 'document_bytes' in payload:
            response = client.analyze_expense(Document={'Bytes': payload['document_bytes']})
        elif 's3_bucket' in payload and 's3_key' in payload:
            response = client.analyze_expense(Document={'S3Object': {'Bucket': payload['s3_bucket'], 'Name': payload['s3_key']}})
        else:
            raise ValueError("Payload must contain either 'document_bytes' or 's3_bucket' and 's3_key'")
    except ClientError as e:
        raise RuntimeError(f"AWS Textract error: {e}")
    normalized = {
        'vendor_name': None,
        'invoice_date': None,
        'total_amount': None,
        'tax_amount': None,
        'line_items': []
    }
    for expense_doc in response.get('ExpenseDocuments', []):
        for summary_field in expense_doc.get('SummaryFields', []):
            label = summary_field.get('Type', {}).get('Text', '').lower()
            value = summary_field.get('ValueDetection', {}).get('Text')
            if 'vendor' in label:
                normalized['vendor_name'] = value
            elif 'date' in label:
                normalized['invoice_date'] = value
            elif 'total' in label and 'tax' not in label:
                normalized['total_amount'] = value
            elif 'tax' in label:
                normalized['tax_amount'] = value
        for line_item_group in expense_doc.get('LineItemGroups', []):
            for line_item in line_item_group.get('LineItems', []):
                item = {}
                for field in line_item.get('LineItemExpenseFields', []):
                    item_label = field.get('Type', {}).get('Text', '').lower()
                    item_value = field.get('ValueDetection', {}).get('Text')
                    if 'description' in item_label:
                        item['description'] = item_value
                    elif 'quantity' in item_label:
                        item['quantity'] = item_value
                    elif 'unit price' in item_label or 'price' in item_label:
                        item['unit_price'] = item_value
                    elif 'amount' in item_label:
                        item['amount'] = item_value
                if item:
                    normalized['line_items'].append(item)
    result = {k: v for k, v in normalized.items() if v is not None}
    return result
